<script lang="ts">
 import type { Resource } from '../../lib/api';
 export let accessMode:'direct'|'agent'='direct'; export let host=''; export let port=8848; export let scheme='http'; export let contextPath='/nacos'; export let username=''; export let password=''; export let accessToken=''; export let timeoutSeconds=10; export let mcpServerResourceId=''; export let mcpServers:Resource[]=[]; export let configurationAttempted=false; export let onConfigurationChange:()=>void=()=>{};
</script>
{#if accessMode==='agent'}<label class:invalid={configurationAttempted&&!mcpServerResourceId}><span><i>*</i>关联 MCPServer</span><select bind:value={mcpServerResourceId} required on:change={onConfigurationChange}><option value="">请选择活动的 MCPServer</option>{#each mcpServers as server}<option value={server.id}>{server.name}</option>{/each}</select></label><p class="docker-field-help">Nacos Agent 通过关联 MCPServer 提供统一只读 API 工具。</p>{:else}<div class="docker-form-grid"><label class:invalid={configurationAttempted&&!host.trim()}><span><i>*</i>Nacos 主机</span><input bind:value={host} required on:input={onConfigurationChange} placeholder="例如 nacos.example.com"/></label><label><span>协议</span><select bind:value={scheme} on:change={onConfigurationChange}><option value="http">HTTP</option><option value="https">HTTPS</option></select></label><label><span>端口</span><input type="number" min="1" max="65535" bind:value={port} on:input={onConfigurationChange}/></label><label><span>上下文路径</span><input bind:value={contextPath} on:input={onConfigurationChange} placeholder="/nacos"/></label><label><span>用户名（可选）</span><input bind:value={username} on:input={onConfigurationChange}/></label><label><span>密码（可选）</span><input type="password" bind:value={password} on:input={onConfigurationChange}/></label><label><span>访问 Token（可选）</span><input type="password" bind:value={accessToken} on:input={onConfigurationChange}/></label><label><span>超时时间（秒）</span><input type="number" min="1" max="300" bind:value={timeoutSeconds} on:input={onConfigurationChange}/></label></div>{/if}
